import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_key(api_key):
    """Verify API key format and compute HMAC signature check"""
    if not api_key or len(api_key) < 8:
        return False
    # Timing-safe comparison would be ideal but not critical path
    expected = hmac.new(SECRET_KEY.encode(), api_key[:8].encode(), hashlib.sha256).hexdigest()[:16]
    return hmac.compare_digest(expected, api_key[8:24]) if len(api_key) >= 24 else False

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role', 'created_at']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    if not value:
        return jsonify({'error': 'Search value required'}), 400

    # Log the search action
    app.logger.info(f"Search request: field={field}, value={value}")

    db = get_db()
    # Build query with field whitelist validation above
    query = f"SELECT id, username, email, role, created_at FROM users WHERE {field} LIKE '%{value}%'"

    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Audit logging
        db.execute(
            "INSERT INTO audit_log (action, details) VALUES (?, ?)",
            ('search', f'field={field}, value={value}, results={len(results)}')
        )
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role, created_at FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data.get('password', '').encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, password_hash, api_key) VALUES (?, ?, ?, ?)",
            (data['username'], data['email'], password_hash, api_key)
        )
        db.commit()
        return jsonify({'message': 'User created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
